package agent
import("fmt";"sort";"strings")
type Layer struct{ID string;Priority int;Categories []Category;Enabled bool;Native bool};type LayerRegistry struct{layers map[string]Layer}
func NewLayerRegistry(layers []Layer)*LayerRegistry{r:=&LayerRegistry{layers:make(map[string]Layer,len(layers))};for _,l:=range layers{l.ID=strings.TrimSpace(l.ID);if l.ID==""||len(l.ID)>256{continue};cats:=make([]Category,0,len(l.Categories));seen:=map[Category]struct{}{};for _,c:=range l.Categories{if strings.TrimSpace(string(c))==""{continue};if _,ok:=seen[c];ok{continue};seen[c]=struct{}{};cats=append(cats,c)};l.Categories=cats;r.layers[l.ID]=l};return r}
func(r *LayerRegistry)Resolve(category Category)(Layer,error){if r==nil{return Layer{},fmt.Errorf("layer registry is required")};category=Category(strings.TrimSpace(string(category)));if category==""{return Layer{},fmt.Errorf("category is required")};var candidates []Layer;for _,l:=range r.layers{if !l.Enabled{continue};for _,c:=range l.Categories{if c==category{candidates=append(candidates,l);break}}};if len(candidates)==0{return Layer{},fmt.Errorf("no enabled layer for category: %s",category)};sort.SliceStable(candidates,func(i,j int)bool{if candidates[i].Native!=candidates[j].Native{return candidates[i].Native};if candidates[i].Priority!=candidates[j].Priority{return candidates[i].Priority<candidates[j].Priority};return candidates[i].ID<candidates[j].ID});return candidates[0],nil}
